package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.ElementTest;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.nodes.ElementTest.validate;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Element_html_TriageGen2Test {

    @Test
    public void testHtml_StringBuilder() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        validate(e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        assertEquals(e.toString(), e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_Empty() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        assertEquals("", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_Simple() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        assertEquals("<div></div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_Complex() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.appendText("Hello");
        assertEquals("<div>Hello</div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_SameTag() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.prependElement("div");
        assertEquals("<div><div></div></div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_DifferentTag() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.prependElement("span");
        assertEquals("<span><div></div></span>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_Text() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.text("Hello");
        assertEquals("<div>Hello</div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_OwnText() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.ownText("Hello");
        assertEquals("<div></div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_InnerText() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.appendText("Hello");
        assertEquals("<div>Hello</div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_ClosingTags() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.appendElement("span");
        assertEquals("<div><span></span></div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_MultipleTags() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.appendElement("span");
        e.appendElement("p");
        assertEquals("<div><span></span><p></p></div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_Attribute() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.attr("id", "myid");
        assertEquals("<div id=\"myid\"></div>", e.html());
    }

    @Test
    public void testHtml_BuildsCorrectly_DataAttribute() {
        Element e = new Element(Tag.valueOf("div"), "", Attributes.none());
        e.html(new StringBuilder());
        e.dataset().put("data-attr", "myvalue");
        assertEquals("<div data-attr=\"myvalue\"></div>", e.html());
    }
}
